//! The generated OpenAPI 3.0 document.
//!
//! GENERATED FROM THE DTO TYPES, CHECKED IN, DRIFT-TESTED. The component
//! schemas come from `schemars` over `crate::contract` and `crate::problem`;
//! the path table below names every route `crate::app::router` serves. The
//! checked-in copy is `schemas/logweir-api-v1.openapi.json`, regenerated by
//! `just schema` and compared by `just schema-check` and by
//! `tests/contract.rs::the_checked_in_openapi_document_is_what_the_types_generate`.
//! Every route's possible problem codes are listed under
//! `x-logweir-problem-codes`, and a test asserts each code in
//! [`crate::problem::ProblemCode::ALL`] appears somewhere.

use schemars::gen::SchemaSettings;
use serde_json::{json, Map, Value};

