/// The document version. `/api/v1` is not yet a stability promise.
pub const DOCUMENT_VERSION: &str = "1.0.0-alpha.1";

fn schema_ref(name: &str) -> Value {
    json!({ "$ref": format!("#/components/schemas/{name}") })
}

fn codes(list: &[ProblemCode]) -> Value {
    Value::Array(
        list.iter()
            .map(|c| Value::String(c.as_str().to_string()))
            .collect(),
    )
}

/// Problem codes any `/api/v1` route can return.
const COMMON: &[ProblemCode] = &[
    ProblemCode::HeaderNotAllowed,
    ProblemCode::MisdirectedRequest,
    ProblemCode::MethodNotAllowed,
    ProblemCode::InternalError,
    ProblemCode::Unauthenticated,
    ProblemCode::SessionExpired,
];

