/// Problem codes a destination route can add.
const DESTINATION: &[ProblemCode] = &[
    ProblemCode::DestinationInvalid,
    ProblemCode::DestinationLocationImmutable,
    ProblemCode::TransportDowngradeForbidden,
];

/// Problem codes a transient-check route can add.
const CHECK: &[ProblemCode] = &[ProblemCode::RateLimited, ProblemCode::NotFound];

/// Problem codes a stored-result page can add.
const RESULT_PAGE: &[ProblemCode] = &[
    ProblemCode::ResultIntegrityFailed,
    ProblemCode::CursorInvalid,
    ProblemCode::CursorExpired,
    ProblemCode::NotFound,
];

/// Problem codes reserved for later stages, with no producing route yet.
const RESERVED: &[ProblemCode] = &[ProblemCode::ApprovalRequired, ProblemCode::PolicyMismatch];

fn all_codes(groups: &[&[ProblemCode]]) -> Vec<ProblemCode> {
    let mut out: Vec<ProblemCode> = Vec::new();
    for group in groups {
        for code in *group {
            if !out.contains(code) {
                out.push(*code);
            }
        }
    }
    out.sort_by_key(|c| c.as_str());
    out
}

struct Op<'a> {
    method: &'static str,
    operation_id: &'a str,
    summary: &'a str,
    parameters: Vec<Value>,
    request: Option<&'a str>,
    success: Vec<(&'a str, &'a str, &'a str)>,
    problems: Vec<ProblemCode>,
}

fn param(name: &str, location: &str, description: &str, schema: Value, required: bool) -> Value {
    json!({
        "name": name,
        "in": location,
        "required": required,
        "description": description,
        "schema": schema,
    })
}

fn ns() -> Value {
    param(
        "ns",
        "path",
        "An explicitly granted namespace. An ungranted namespace is namespace_forbidden whether or not it exists.",
        json!({ "type": "string" }),
        true,
    )
}

fn name() -> Value {
    param(
        "name",
        "path",
        "The object name.",
        json!({ "type": "string" }),
        true,
    )
}

fn id() -> Value {
    param(
        "id",
        "path",
        "The check's id, which is its object name.",
        json!({ "type": "string" }),
        true,
    )
}

fn list_params() -> Vec<Value> {
    vec![
        ns(),
        param(
            "limit",
            "query",
            "Page size, 1 to 200. Default 50.",
            json!({ "type": "integer", "minimum": 1, "maximum": 200, "default": 50 }),
            false,
        ),
        param(
            "cursor",
            "query",
            "The opaque nextCursor of the previous page. Bound to actor, route, namespace and filters; expires after 15 minutes.",
            json!({ "type": "string" }),
            false,
        ),
        param(
            "labelSelector",
            "query",
            "Equality-only label selector, key=value terms separated by commas.",
            json!({ "type": "string" }),
            false,
        ),
    ]
}

fn idempotency_key() -> Value {
    param(
        "Idempotency-Key",
        "header",
        "8 to 128 visible ASCII characters. The object name is derived from (actor, namespace, route, key); a replay of the same request returns 200 with the same object, a different request with the same key is idempotency_conflict.",
        json!({ "type": "string", "minLength": 8, "maxLength": 128 }),
        true,
    )
}

fn origin() -> Value {
    param(
        "Origin",
        "header",
        "Must equal the configured public origin exactly.",
        json!({ "type": "string" }),
        true,
    )
}

fn operation(op: &Op<'_>) -> Value {
    let mut responses = Map::new();
    for (status, description, schema) in &op.success {
        // An empty schema name means a response with NO body: a 204, or a 303
        // whose only payload is `Location` and `Set-Cookie`. Emitting
        // `$ref: #/components/schemas/` for those would be an invalid document.
        let response = if schema.is_empty() {
            json!({ "description": description })
        } else {
            json!({
                "description": description,
                "content": { "application/json": { "schema": schema_ref(schema) } }
            })
        };
        responses.insert((*status).to_string(), response);
    }
    responses.insert(
        "default".to_string(),
        json!({
            "description": "An application/problem+json error; the possible codes are listed in x-logweir-problem-codes.",
            "content": { "application/problem+json": { "schema": schema_ref("Problem") } }
        }),
    );
    let mut out = Map::new();
    out.insert("operationId".into(), json!(op.operation_id));
    out.insert("summary".into(), json!(op.summary));
    if !op.parameters.is_empty() {
        out.insert("parameters".into(), Value::Array(op.parameters.clone()));
    }
    if let Some(request) = op.request {
        out.insert(
            "requestBody".into(),
            json!({
                "required": true,
                "content": { "application/json": { "schema": schema_ref(request) } }
            }),
        );
    }
    out.insert("responses".into(), Value::Object(responses));
    out.insert("x-logweir-problem-codes".into(), codes(&op.problems));
    Value::Object(out)
}

